RULE = "ACTION4 shifts both aligned agent tiles one slot right along the bar; at the rightmost slot they wrap to the leftmost slot"
PARAMS = {"agent": Colour(), "step": Int(1, 16)}

def _tiles(board, api, p):
    objs = objects(board, api, colour=p["agent"])
    if len(objs) != 2:
        return None
    a, b = objs
    if a.box[2] != b.box[2] or a.box[3] != b.box[3]:
        return None
    if a.box[1] - a.box[0] != 1 or b.box[1] - b.box[0] != 1:
        return None
    return sorted((a, b), key=lambda o: o.box[0])

def _track(api, p, tiles):
    ay0, ay1 = tiles[0].box[0], tiles[1].box[1]
    ax0, ax1 = tiles[0].box[2], tiles[0].box[3]
    best = None
    for r in api.layout:
        h = r.y1 - r.y0 + 1
        w = r.x1 - r.x0 + 1
        if w < 2 * p["step"] or h > 2 * p["step"]:
            continue
        if not (r.x0 <= ax0 and r.x1 >= ax1):
            continue
        if r.y1 < ay0:
            gap = ay0 - r.y1 - 1
        elif r.y0 > ay1:
            gap = r.y0 - ay1 - 1
        else:
            gap = 0
        if gap > 4:
            continue
        mult = 0 if w % p["step"] == 0 else 1
        key = (mult, gap)
        if best is None or key < best[0]:
            best = (key, r)
    return best[1] if best else None

def _move(board, api, p):
    tiles = _tiles(board, api, p)
    if tiles is None:
        return None
    track = _track(api, p, tiles)
    if track is None:
        return None
    w = tiles[0].box[3] - tiles[0].box[2] + 1
    step = p["step"]
    inset = (step - w) // 2
    left = track.x0 + inset
    right = track.x1 - inset
    moves = []
    for t in tiles:
        x0 = t.box[2]
        nx = x0 + step
        if nx + w - 1 > right:
            nx = left
        if nx == x0:
            return None
        if np.any(board[t.box[0]:t.box[1] + 1, nx:nx + w] == p["agent"]):
            return None
        moves.append((t, nx))
    return moves

def bind(board, api):
    objs = objects(api.first, api)
    by_colour = {}
    for o in objs:
        by_colour.setdefault(o.colour, []).append(o)
    agent = None
    for c, lst in by_colour.items():
        if len(lst) == 2:
            a, b = lst
            if (a.box[2] == b.box[2] and a.box[3] == b.box[3]
                    and a.box[1] - a.box[0] == 1 and b.box[1] - b.box[0] == 1):
                agent = c
                break
    if agent is None and objs:
        agent = min(objs, key=lambda o: o.size).colour
    w = 0
    for o in objs:
        if o.colour == agent:
            w = o.box[3] - o.box[2] + 1
            break
    step = min(16, max(1, w + 2))
    return {"agent": agent, "step": step}

def applies(board, act, api, p):
    if act.action != 4:
        return False
    return _move(board, api, p) is not None

def predict(board, act, api, p):
    moves = _move(board, api, p)
    if moves is None:
        return board.copy(), np.zeros((64, 64), dtype=bool)
    out = board.copy()
    claimed = np.zeros((64, 64), dtype=bool)
    for t, nx in moves:
        w = t.box[3] - t.box[2] + 1
        x0 = t.box[2]
        ma = np.zeros((64, 64), dtype=bool)
        ma[t.box[0]:t.box[1] + 1, x0:x0 + w] = True
        mb = np.zeros((64, 64), dtype=bool)
        mb[t.box[0]:t.box[1] + 1, nx:nx + w] = True
        out, cl = swap(out, api, ma, mb)
        claimed |= cl
    return out, claimed

RULE = "ACTION1 moves every agent block up by `step` rows when the `step`-row band directly above it is entirely track colour (old cells become track)"
PARAMS = {"agent": Colour(), "track": Colour(), "step": Int(1, 8)}

def bind(board, api):
    if not api.layout:
        return {"agent": None, "track": None, "step": 5}
    agent = min(api.layout, key=lambda r: r.size).colour
    track = api.layout[0].colour
    objs = objects(api.first, api, colour=agent)
    step = 5
    if objs:
        step = max(o.y1 - o.y0 + 1 for o in objs)
    step = min(max(int(step), 1), 8)
    return {"agent": agent, "track": track, "step": step}

def applies(board, act, api, p):
    if act.action != 1:
        return False
    return bool(objects(board, api, colour=p["agent"]))

def predict(board, act, api, p):
    H, W = board.shape
    out = board.copy()
    claimed = np.zeros((H, W), bool)
    objs = objects(board, api, colour=p["agent"])
    if not objs:
        return out, claimed
    step = int(p["step"])
    if step <= 0 or step >= H:
        return out, claimed
    for o in objs:
        m = o.mask
        new_mask = np.zeros((H, W), bool)
        new_mask[:H - step, :] = m[step:, :]
        if not new_mask.any():
            continue
        need = new_mask & ~m          # cells the block moves into
        if not need.any():
            continue
        if not np.all(board[need] == p["track"]):
            continue
        out[m] = p["track"]           # old cells become track
        out[new_mask] = p["agent"]    # new cells become agent
        claimed[m] = True
        claimed[new_mask] = True
    return out, claimed

RULE = "ACTION2 slides each small agent-coloured block down by step rows when the cells below are the cage colour, else it stays"
