def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, dtype=bool)
    for o in objects(board, api, colour=p["agent"]):
        m = o.mask
        ys, xs = np.nonzero(m)
        ys2 = ys + p["step"]
        moved = False
        if (ys2 < 64).all():
            dest = np.zeros(board.shape, dtype=bool)
            dest[ys2, xs] = True
            if np.all(board[dest] == p["cage"]):
                out[m] = p["cage"]
                out[dest] = p["agent"]
                claimed |= m | dest
                moved = True
        if not moved:
            claimed |= m
    return out, claimed

