def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, dtype=bool)
    any_moved = False
    for obj in objects(board, api, colour=p["agent"]):
        y0, y1, x0, x1 = obj.box
        if y1 + p["step"] >= 64:
            continue
        m = obj.mask
        target = np.zeros_like(m)
        target[y0 + p["step"]:y1 + p["step"] + 1, x0:x1 + 1] = m[y0:y1 + 1, x0:x1 + 1]
        if not np.all(board[target] == p["behind"]):
            continue
        out[m] = p["behind"]
        out[target] = p["agent"]
        claimed |= (m | target)
        any_moved = True
    if not any_moved:
        cells = np.zeros(board.shape, dtype=bool)
        for obj in objects(board, api, colour=p["agent"]):
            cells |= obj.mask
        return unchanged(board, cells)
    return out, claimed

