RULE = "clicking a colour swatch (or its frame) in the top bar paints the interior of the framed shape with that colour"
PARAMS = {"frame": Colour()}

def _tby(api, board):
    W = board.shape[1]
    for reg in api.layout:
        if reg.y0 == 0 and reg.x1 == W - 1:
            return reg.y1
    return 8

def _dil(m):
    return m | np.roll(m, 1, 0) | np.roll(m, -1, 0) | np.roll(m, 1, 1) | np.roll(m, -1, 1)

def _component(cand, seed):
    comp = np.zeros(cand.shape, bool)
    comp[seed] = True
    for _ in range(300):
        new = comp | (_dil(comp) & cand)
        if (new == comp).all():
            break
        comp = new
    return comp

def _interior(board, frame, bg):
    fm = (board == frame)
    if not fm.any():
        return None
    cand = (board != bg) & (board != frame)
    if not cand.any():
        return None
    ys, xs = np.where(fm)
    cy, cx = ys.mean(), xs.mean()
    cys, cxs = np.where(cand)
    d = (cys - cy) ** 2 + (cxs - cx) ** 2
    i = int(np.argmin(d))
    return _component(cand, (cys[i], cxs[i]))

def _ring_uniform(board, reg):
    y0, x0, y1, x1 = reg.y0, reg.x0, reg.y1, reg.x1
    if y0 <= 0 or x0 <= 0 or y1 >= board.shape[0] - 1 or x1 >= board.shape[1] - 1:
        return False
    area = board[y0 - 1:y1 + 2, x0 - 1:x1 + 2]
    mask = ~reg.mask[y0 - 1:y1 + 2, x0 - 1:x1 + 2]
    cells = area[mask]
    return cells.size > 0 and (cells == cells[0]).all() and cells[0] != reg.colour

def _swatches(board, api):
    tby = _tby(api, board)
    out = []
    for reg in api.layout:
        if reg.colour == api.background or reg.size > 25 or reg.y1 > tby:
            continue
        h = reg.y1 - reg.y0 + 1
        w = reg.x1 - reg.x0 + 1
        if h < 2 or w < 2 or abs(h - w) > 1 or reg.size / (h * w) < 0.8:
            continue
        if _ring_uniform(board, reg):
            out.append(reg)
    return out

def _hit(board, api, r, c):
    for reg in _swatches(board, api):
        if reg.y0 - 1 <= r <= reg.y1 + 1 and reg.x0 - 1 <= c <= reg.x1 + 1:
            return reg
    return None

def bind(board0, api):
    tby = _tby(api, board0)
    rows = np.arange(board0.shape[0])[:, None]
    play = (board0 != api.background) & (rows > tby)
    best, bestsz = None, -1
    for c in np.unique(board0[play]):
        fm = (board0 == c)
        cand = (board0 != api.background) & (board0 != c)
        if not cand.any():
            continue
        ys, xs = np.where(fm)
        cy, cx = ys.mean(), xs.mean()
        cys, cxs = np.where(cand)
        i = int(np.argmin((cys - cy) ** 2 + (cxs - cx) ** 2))
        comp = _component(cand, (cys[i], cxs[i]))
        if comp.size <= 0:
            continue
        bys, bxs = np.where(comp)
        fys, fxs = np.where(fm)
        if fys.min() <= bys.min() and fys.max() >= bys.max() and fxs.min() <= bxs.min() and fxs.max() >= bxs.max():
            if comp.size > bestsz:
                bestsz, best = comp.size, int(c)
    return {"frame": best} if best is not None else {}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    if _hit(board, api, r, c) is None:
        return False
    return _interior(board, p["frame"], api.background) is not None

def predict(board, act, api, p):
    out = board.copy()
    r, c = act.click
    reg = _hit(board, api, r, c)
    interior = _interior(board, p["frame"], api.background) if reg is not None else None
    if interior is None:
        return out, np.zeros(board.shape, dtype=bool)
    out[interior] = reg.colour
    return out, interior

RULE = "Clicking a palette swatch fills the selected (framed) playfield object with that swatch's colour"
PARAMS = {"swatch_frame": Colour(), "sel_frame": Colour()}

def _inside(o, f):
    return o.box[0] > f.box[0] and o.box[1] < f.box[1] and o.box[2] > f.box[2] and o.box[3] < f.box[3]

def _frames_with_inner(board, api):
    objs = objects(board, api)
    res = []
    for f in objs:
        inners = [o for o in objs if o is not f and _inside(o, f)]
        if len(inners) == 1:
            res.append((f, inners[0]))
    return res

def _palette_frames(board, api):
    # the palette = a group of >=2 same-colour frames aligned at the same top rows
    groups = {}
    for f, o in _frames_with_inner(board, api):
        if f.box[0] > 8:
            continue
        groups.setdefault((f.colour, f.box[0], f.box[1]), []).append(f)
    best = None
    for key, lst in groups.items():
        if len(lst) >= 2 and (best is None or len(lst) > len(best[1])):
            best = (key, lst)
    return best[1] if best else []

def bind(board0, api):
    pf = _palette_frames(board0, api)
    swatch_frame = pf[0].colour if pf else api.background
    sel_frame = api.background
    for f, o in _frames_with_inner(board0, api):
        if f.box[0] > 10:
            sel_frame = f.colour
            break
    return {"swatch_frame": swatch_frame, "sel_frame": sel_frame}

def _is_swatch(board, act, api, p):
    o = object_at(board, api, act.click)
    if o is None:
        return None
    for f in _palette_frames(board, api):
        if f.colour == p["swatch_frame"] and _inside(o, f):
            return o
    return None

def _selected(board, api, p):
    for f, o in _frames_with_inner(board, api):
        if f.colour == p["sel_frame"] and f.box[0] > 10:
            return o
    return None

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    if _is_swatch(board, act, api, p) is None:
        return False
    return _selected(board, api, p) is not None

def predict(board, act, api, p):
    o = _is_swatch(board, act, api, p)
    sel = _selected(board, api, p)
    if o is None or sel is None:
        return unchanged(board, np.zeros(board.shape, dtype=bool))
    return recolour(board, api, sel, o.colour)

RULE = "clicking a palette slot recolors the framed play shape to the slot's colour"
PARAMS = {"frame": Colour()}

def _inside(frame, o):
    return o.box[0] > frame.box[0] and o.box[1] < frame.box[1] and o.box[2] > frame.box[2] and o.box[3] < frame.box[3]

def _shape_in_frame(board, api, frame):
    cands = [o for o in objects(board, api) if _inside(frame, o)]
    if not cands:
        return None
    return max(cands, key=lambda o: o.size)

def _is_swatch(board, api, clicked):
    for R in objects(board, api):
        if R.colour == clicked.colour:
            continue
        if not (R.box[0] < clicked.box[0] and R.box[1] > clicked.box[1] and R.box[2] < clicked.box[2] and R.box[3] > clicked.box[3]):
            continue
        h = R.box[1] - R.box[0] + 1
        w = R.box[3] - R.box[2] + 1
        if R.size < 2 * h + 2 * w - 4:
            continue
        interior = np.zeros_like(clicked.mask)
        interior[R.box[0] + 1:R.box[1], R.box[2] + 1:R.box[3]] = True
        if np.array_equal(interior, clicked.mask):
            return True
    return False

def bind(board, api):
    best = None
    for o in objects(api.first, api):
        h = o.box[1] - o.box[0] + 1
        w = o.box[3] - o.box[2] + 1
        if o.size == 2 * h + 2 * w - 4 and (best is None or o.size > best.size):
            best = o
    return {"frame": best.colour if best is not None else api.background}

def applies(board, act, api, p):
    if act.click is None:
        return False
    clicked = object_at(board, api, act.click)
    if clicked is None or not _is_swatch(board, api, clicked):
        return False
    frame = find_object(board, api, p["frame"])
    if frame is None:
        return False
    shape = _shape_in_frame(board, api, frame)
    return shape is not None and shape.colour != clicked.colour

def predict(board, act, api, p):
    clicked = object_at(board, api, act.click)
    frame = find_object(board, api, p["frame"])
    shape = _shape_in_frame(board, api, frame)
    if shape is None or shape.colour == clicked.colour:
        return unchanged(board, shape)
    return recolour(board, api, shape, clicked.colour)

RULE = "clicking a colour swatch (a small square in the top bar) paints the interior of the framed shape with that colour; clicking the underline indicator does nothing"
PARAMS = {"frame": Colour()}

def _tby(api, board):
    H, W = board.shape
    for reg in api.layout:
        if reg.y0 == 0 and reg.x1 == W - 1:
            return reg.y1
    ys = [reg.y1 for reg in api.layout if reg.y0 == 0]
    return max(ys) if ys else 0

def _topbar_col(api, board):
    W = board.shape[1]
    for reg in api.layout:
        if reg.y0 == 0 and reg.x1 == W - 1:
            return reg.colour
    return None

def _is_swatch(reg, tby, topbar_col, bg):
    if reg.colour == bg or reg.colour == topbar_col:
        return False
    if reg.y1 >= tby or reg.size > 25:
        return False
    h = reg.y1 - reg.y0 + 1
    w = reg.x1 - reg.x0 + 1
    if h < 2 or w < 2:          # exclude the 1-row underline indicator
        return False
    if abs(h - w) > 1:          # swatches are square-ish, indicator is a wide line
        return False
    a = h * w
    return reg.size / a > 0.8

def _dil(m):
    return m | np.roll(m, 1, 0) | np.roll(m, -1, 0) | np.roll(m, 1, 1) | np.roll(m, -1, 1)

def _component(cand, seed):
    comp = np.zeros(cand.shape, bool)
    comp[seed] = True
    for _ in range(300):
        new = comp | (_dil(comp) & cand)
        if (new == comp).all():
            break
        comp = new
    return comp

def _interior(board, frame, bg):
    fm = (board == frame)
    if not fm.any():
        return None
    cand = (board != bg) & (board != frame)
    if not cand.any():
        return None
    ys, xs = np.where(fm)
    cy, cx = ys.mean(), xs.mean()
    cys, cxs = np.where(cand)
    d = (cys - cy) ** 2 + (cxs - cx) ** 2
    i = int(np.argmin(d))
    return _component(cand, (cys[i], cxs[i]))

def bind(board0, api):
    tby = _tby(api, board0)
    H = board0.shape[0]
    rows = np.arange(H)[:, None]
    play = (board0 != api.background) & (rows > tby)
    best, bestsz = None, -1
    for c in np.unique(board0[play]):
        fm = (board0 == c)
        cand = (board0 != api.background) & (board0 != c)
        if not cand.any():
            continue
        ys, xs = np.where(fm)
        cy, cx = ys.mean(), xs.mean()
        cys, cxs = np.where(cand)
        i = int(np.argmin((cys - cy) ** 2 + (cxs - cx) ** 2))
        comp = _component(cand, (cys[i], cxs[i]))
        if comp.size <= 0:
            continue
        bys, bxs = np.where(comp)
        fys, fxs = np.where(fm)
        if fys.min() <= bys.min() and fys.max() >= bys.max() and fxs.min() <= bxs.min() and fxs.max() >= bxs.max():
            if comp.size > bestsz:
                bestsz, best = comp.size, int(c)
    return {"frame": best} if best is not None else {}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    tby = _tby(api, board)
    if r >= tby:
        return False
    topbar_col = _topbar_col(api, board)
    c0 = board[r, c]
    ok = False
    for reg in api.layout:
        if reg.colour == c0 and reg.mask[r, c] and _is_swatch(reg, tby, topbar_col, api.background):
            ok = True
            break
    if not ok:
        return False
    return _interior(board, p["frame"], api.background) is not None

def predict(board, act, api, p):
    out = board.copy()
    r, c = act.click
    swatch = board[r, c]
    interior = _interior(board, p["frame"], api.background)
    if interior is None:
        return out, np.zeros(board.shape, dtype=bool)
    out[interior] = swatch
    return out, interior

RULE = "clicking a palette slot recolors the framed shape to that slot's colour and moves the selection underline to it"
PARAMS = {"border": Colour()}

def _dil(m):
    d = m.copy()
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dy or dx:
                d |= np.roll(np.roll(m, dy, 0), dx, 1)
    return d

def _comp(board, r, c, col):
    H, W = board.shape
    seen = {(r, c)}; st = [(r, c)]
    while st:
        y, x = st.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W and (ny, nx) not in seen and board[ny, nx] == col:
                seen.add((ny, nx)); st.append((ny, nx))
    return seen

def _slot(board, r, c, col, bg):
    if board[r, c] != col:
        return None
    comp = _comp(board, r, c, col)
    ys = [y for y, x in comp]; xs = [x for y, x in comp]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    h, w = y1 - y0 + 1, x1 - x0 + 1
    if h < 3 or w < 3:
        return None
    sub = (board[y0:y1 + 1, x0:x1 + 1] == col)
    per = np.zeros((h, w), bool)
    per[0, :] = True; per[-1, :] = True; per[:, 0] = True; per[:, -1] = True
    if not np.array_equal(sub, per):
        return None
    inter = board[y0 + 1:y1, x0 + 1:x1]
    if inter.size == 0 or len(np.unique(inter)) != 1:
        return None
    inner = int(inter[0, 0])
    if y1 + 1 >= board.shape[0]:
        return None
    row = board[y1 + 1, x0:x1 + 1]
    if len(np.unique(row)) != 1:
        return None
    ul = int(row[0])
    if ul == bg or ul == col:
        return None
    return {"y0": y0, "x0": x0, "y1": y1, "x1": x1, "inner": inner, "underline": ul}

def _all_slots(board, col, bg):
    out = []; seen = set()
    for (y, x) in zip(*np.where(board == col)):
        if (int(y), int(x)) in seen:
            continue
        comp = _comp(board, int(y), int(x), col); seen |= comp
        s = _slot(board, int(y), int(x), col, bg)
        if s:
            out.append(s)
    return out

def _active_fill(board, bg, border):
    slots = _all_slots(board, border, bg)
    if not slots:
        return np.zeros(board.shape, bool)
    top = max(s["y1"] for s in slots) + 1
    play = np.zeros(board.shape, bool)
    play[top + 1:, :] = True
    cand = (board != bg) & (~_dil(board == bg)) & play
    if not cand.any():
        return np.zeros(board.shape, bool)
    pts = {(int(y), int(x)) for y, x in zip(*np.where(cand))}
    best = set(); seen = set()
    for p0 in pts:
        if p0 in seen:
            continue
        comp = {p0}; st = [p0]
        while st:
            y, x = st.pop()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (y + dy, x + dx)
                if q in pts and q not in comp:
                    comp.add(q); st.append(q)
        seen |= comp
        if len(comp) > len(best):
            best = comp
    m = np.zeros(board.shape, bool)
    for (y, x) in best:
        m[y, x] = True
    return m

def bind(board0, api):
    for col in api.colours:
        if len(_all_slots(board0, int(col), api.background)) >= 2:
            return {"border": int(col)}
    return {}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    return _slot(board, r, c, p["border"], api.background) is not None

def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, bool)
    r, c = act.click
    S = _slot(board, r, c, p["border"], api.background)
    if S is None:
        return out, claimed
    A = _active_fill(board, api.background, p["border"])
    if not A.any():
        return out, claimed
    shape_col = int(np.bincount(board[A].ravel()).argmax())
    slots = _all_slots(board, p["border"], api.background)
    T = None
    for s in slots:
        if s["inner"] == shape_col:
            T = s
            break
    if T is None or T == S:
        return out, claimed
    sel = T["underline"]
    unsel = None
    for s in slots:
        if s is not T and s["underline"] != sel:
            unsel = s["underline"]
            break
    if unsel is None:
        return out, claimed
    out[A] = S["inner"]
    claimed |= A
    out[S["y1"] + 1, S["x0"]:S["x1"] + 1] = sel
    claimed[S["y1"] + 1, S["x0"]:S["x1"] + 1] = True
    out[T["y1"] + 1, T["x0"]:T["x1"] + 1] = unsel
    claimed[T["y1"] + 1, T["x0"]:T["x1"] + 1] = True
    return out, claimed

RULE = "ACTION5 moves the agent block to its home cell (the 5x5 home region becomes the agent colour, centre keeps its base colour)"
PARAMS = {"agent": Colour(), "home": Region()}

def bind(board0, api):
    cands = [r for r in api.layout if r.size <= 40]
    if not cands:
        return {}
    cands.sort(key=lambda r: (r.y0, r.x0))
    home = cands[0]
    return {"agent": home.colour, "home": home}

def _home_mask(api, p):
    h = p["home"]
    yy, xx = np.mgrid[0:64, 0:64]
    m = (yy >= h.y0) & (yy <= h.y1) & (xx >= h.x0) & (xx <= h.x1)
    cy = (h.y0 + h.y1) // 2
    cx = (h.x0 + h.x1) // 2
    m = m & ~((yy == cy) & (xx == cx))
    return m, cy, cx

def applies(board, act, api, p):
    if act.action != 5:
        return False
    if not (board == p["agent"]).any():
        return False
    m, cy, cx = _home_mask(api, p)
    # agent is at home if all home cells are agent colour
    if (board[m] == p["agent"]).all():
        return False
    return True

def predict(board, act, api, p):
    out = board.copy()
    m, cy, cx = _home_mask(api, p)
    out[m] = p["agent"]
    return out, m

RULE = "ACTION5 moves the agent block off its current cell (the cell reverts to the maze colour); it does nothing when the agent is at its home cell or on the path"
PARAMS = {"agent": Colour(), "size": Int(3, 8)}

def _detect(board, color, maze, s):
    mask = (board == color).astype(np.int32)
    H, W = board.shape
    P = np.zeros((H + 1, W + 1), np.int32)
    P[1:, 1:] = mask.cumsum(0).cumsum(1)
    S = P[s:, s:] - P[:-s, s:] - P[s:, :-s] + P[:-s, :-s]
    off = s // 2
    cand = (S == s * s - 1) & (board[off:off + H + 1 - s, off:off + W + 1 - s] == maze)
    if not cand.any():
        return None
    rows, cols = np.where(cand)
    r = int(rows.min())
    c = int(cols[rows == r].min())
    return (r, c)

def bind(board0, api):
    maze = api.layout[0].colour
    for s in range(3, 9):
        for c in api.colours:
            if c == api.background or c == maze:
                continue
            if _detect(board0, c, maze, s) is not None:
                return {"agent": c, "size": s}
    return {}

def applies(board, act, api, p):
    if act.action != 5:
        return False
    maze = api.layout[0].colour
    agent = p["agent"]
    s = p["size"]
    pos = _detect(board, agent, maze, s)
    if pos is None:
        return False
    home = _detect(api.first, agent, maze, s)
    if pos == home:
        return False
    r, c = pos
    H, W = board.shape
    obs = [c for c in api.colours if c not in (api.background, maze, agent)]
    if obs:
        a = max(0, r - 1); b = min(H, r + s + 1)
        cc = max(0, c - 1); d = min(W, c + s + 1)
        if np.isin(board[a:b, cc:d], obs).any():
            return False
    return True

def predict(board, act, api, p):
    maze = api.layout[0].colour
    agent = p["agent"]
    s = p["size"]
    pos = _detect(board, agent, maze, s)
    H, W = board.shape
    out = board.copy()
    if pos is None:
        return out, np.zeros((H, W), bool)
    r, c = pos
    out[r:r + s, c:c + s] = maze
    claimed = np.zeros((H, W), bool)
    claimed[r:r + s, c:c + s] = True
    return out, claimed

RULE = "clicking the 2-D handle on the right rotates the ring of square tiles one step clockwise"
PARAMS = {"agent": Colour()}

def bind(board, api):
    best = None
    for o in objects(board, api):
        t, b, l, r = o.box
        w, h = r - l + 1, b - t + 1
        if w > 1 and h > 1 and not (w % 4 == 0 and h % 4 == 0 and o.size == w * h):
            if best is None or l > best.box[2]:
                best = o
    if best is not None:
        return {"agent": best.colour}
    if api.layout:
        return {"agent": api.layout[0].colour}
    return {"agent": api.background}

def _ring(board, api):
    H, W = board.shape
    objs = objects(board, api)
    tiles = []
    for o in objs:
        t, b, l, r = o.box
        w, h = r - l + 1, b - t + 1
        if w >= 4 and h >= 4 and w % 4 == 0 and h % 4 == 0 and o.size == w * h:
            tiles.append(o)
    if len(tiles) < 4:
        return None
    s = min(min(o.box[3] - o.box[2] + 1, o.box[1] - o.box[0] + 1) for o in tiles)
    if s < 2:
        return None
    mask = np.zeros((H, W), bool)
    for o in tiles:
        mask |= o.mask
    m = mask.astype(np.int32)
    cs = np.zeros((H + 1, W + 1), np.int32)
    cs[1:, 1:] = m.cumsum(0).cumsum(1)
    S = cs[s:, s:] - cs[:-s, s:] - cs[s:, :-s] + cs[:-s, :-s]
    cov = S == s * s
    origins = np.argwhere(cov)
    if len(origins) < 8:
        return None
    ys = np.unique(origins[:, 0]); xs = np.unique(origins[:, 1])
    if len(ys) < 4 or len(xs) < 4:
        return None
    if not (np.diff(ys) == np.diff(ys)[0]).all() or not (np.diff(xs) == np.diff(xs)[0]).all():
        return None
    nrow, ncol = len(ys), len(xs)
    L = []
    for j in range(ncol):
        L.append((0, j))
    for i in range(1, nrow):
        L.append((i, ncol - 1))
    for j in range(ncol - 2, -1, -1):
        L.append((nrow - 1, j))
    for i in range(nrow - 2, 0, -1):
        L.append((i, 0))
    colmap = {}
    for (i, j) in L:
        if not cov[ys[i], xs[j]]:
            return None
        colmap[(i, j)] = int(board[ys[i], xs[j]])
    return L, colmap, ys, xs, s

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    o = object_at(board, api, act.click)
    if o is None or o.colour != p["agent"]:
        return False
    t, b, l, r = o.box
    if (r - l + 1) <= 1 or (b - t + 1) <= 1:
        return False
    return _ring(board, api) is not None

def predict(board, act, api, p):
    res = _ring(board, api)
    if res is None:
        return board.copy(), np.zeros(board.shape, bool)
    L, colmap, ys, xs, s = res
    out = board.copy()
    claimed = np.zeros(board.shape, bool)
    n = len(L)
    for idx, (i, j) in enumerate(L):
        c = colmap[L[(idx - 1) % n]]
        out[ys[i]:ys[i] + s, xs[j]:xs[j] + s] = c
        claimed[ys[i]:ys[i] + s, xs[j]:xs[j] + s] = True
    return out, claimed

RULE = "clicking the paint swatch recolors the frame-selected object to the swatch colour"
PARAMS = {"paint": Colour(), "frame": Colour()}

def _target(board, api, p, sw):
    objs = objects(board, api)
    cands = []
    for f in objs:
        if f.colour != p["frame"]:
            continue
        f0, f1, f2, f3 = f.box
        ty0, ty1, tx0, tx1 = f0 + 1, f1 - 1, f2 + 1, f3 - 1
        if ty1 <= ty0 or tx1 <= tx0:
            continue
        for o in objs:
            if o is f:
                continue
            b = o.box
            if b[0] == ty0 and b[1] == ty1 and b[2] == tx0 and b[3] == tx1 and o.size > sw.size:
                cands.append(o)
    return cands[0] if len(cands) == 1 else None

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    sw = object_at(board, api, act.click)
    if sw is None or sw.colour != p["paint"]:
        return False
    # the swatch is the small paint object; the corner pattern is the big one
    if not any(o.size > sw.size for o in objects(board, api, colour=p["paint"])):
        return False
    return _target(board, api, p, sw) is not None

def predict(board, act, api, p):
    sw = object_at(board, api, act.click)
    t = _target(board, api, p, sw)
    if t is None:
        return unchanged(board, np.zeros((64, 64), bool))
    return recolour(board, api, t, p["paint"])

RULE = "Clicking a palette swatch slides the 1x5 selection bar to sit under that swatch"
PARAMS = {"frame": Colour(), "bar": Colour()}

def bind(board, api):
    for o in objects(board, api):
        if (o.box[1] - o.box[0]) == 4 and (o.box[3] - o.box[2]) == 4 and o.size == 16:
            for b in objects(board, api):
                if b.box[0] == o.box[1] + 1 and b.box[1] == b.box[0] and b.size == 5:
                    return {"frame": o.colour, "bar": b.colour}
            return {"frame": o.colour, "bar": api.background}
    return {"frame": api.colours[0], "bar": api.background}

def _find(board, api, p, r, c):
    frame = None
    for o in objects(board, api, colour=p["frame"]):
        if o.box[0] <= r <= o.box[1] and o.box[2] <= c <= o.box[3]:
            frame = o
            break
    if frame is None:
        return None, None
    bar = None
    for b in objects(board, api, colour=p["bar"]):
        if b.box[0] == frame.box[1] + 1 and b.box[1] == b.box[0] and b.size == 5:
            bar = b
            break
    return frame, bar

def applies(board, act, api, p):
    if act.click is None:
        return False
    r, c = act.click
    frame, bar = _find(board, api, p, r, c)
    if frame is None or bar is None:
        return False
    return (bar.box[2] + bar.box[3]) // 2 != (frame.box[2] + frame.box[3]) // 2

def predict(board, act, api, p):
    r, c = act.click
    frame, bar = _find(board, api, p, r, c)
    if frame is None or bar is None:
        return unchanged(board, frame if frame is not None else bar)
    dx = (frame.box[2] + frame.box[3]) // 2 - (bar.box[2] + bar.box[3]) // 2
    if dx == 0:
        return unchanged(board, bar)
    behind = board[bar.box[0], bar.box[2] - 1] if bar.box[2] > 0 else api.background
    return translate(board, api, bar, 0, dx, behind=behind)

RULE = "ACTION1 moves the 2x2 agent block up by step rows onto the solid block above it"
PARAMS = {"agent": Colour(), "step": Int(1, 8)}

def bind(board0, api):
    best = None
    for c in api.colours:
        m = board0 == c
        tl = m[:-1, :-1] & m[1:, :-1] & m[:-1, 1:] & m[1:, 1:]
        if tl.any():
            n = int(m.sum())
            if best is None or n < best[1]:
                best = (int(c), n)
    return {"agent": best[0], "step": 2} if best else {}

def _agent(board, p):
    m = board == p["agent"]
    tl = m[:-1, :-1] & m[1:, :-1] & m[:-1, 1:] & m[1:, 1:]
    if tl.sum() != 1:
        return None
    r, c = np.argwhere(tl)[0]
    return int(r), int(c)

def applies(board, act, api, p):
    if act.action != 1:
        return False
    a = _agent(board, p)
    if a is None:
        return False
    r, c = a
    s = p["step"]
    if r - s < 0:
        return False
    above = board[r - s:r - s + 2, c:c + 2]
    col = above[0, 0]
    if col == p["agent"] or col == api.background:
        return False
    return bool((above == col).all())

def predict(board, act, api, p):
    r, c = _agent(board, p)
    s = p["step"]
    out = board.copy()
    out[r - s:r - s + 2, c:c + 2] = p["agent"]
    claimed = np.zeros((64, 64), dtype=bool)
    claimed[r - s:r - s + 2, c:c + 2] = True
    return out, claimed

RULE = "ACTION3 swaps the agent's 2x2 block with the solid 2x2 block directly to its left, only when that left block is not part of a wider same-colour run"
PARAMS = {"agent": Colour(), "d": Int(2, 8)}

def _tl2x2(board, c):
    g = board == c
    t = g[:-1, :-1] & g[1:, :-1] & g[:-1, 1:] & g[1:, 1:]
    ys, xs = np.where(t)
    return list(zip(ys.tolist(), xs.tolist()))

def bind(board0, api):
    bg = api.background
    for c in api.colours:
        if c == bg:
            continue
        blocks = _tl2x2(board0, c)
        if len(blocks) != 1:
            continue
        y0, x0 = blocks[0]
        if x0 >= 2:
            left = board0[y0:y0+2, x0-2:x0]
            u = np.unique(left)
            if len(u) == 1 and u[0] != bg:
                return {"agent": c, "d": 4}
    for c in api.colours:
        if c != bg and len(_tl2x2(board0, c)) == 1:
            return {"agent": c, "d": 4}
    return {}

def _agent_block(board, p):
    blocks = _tl2x2(board, p["agent"])
    if len(blocks) != 1:
        return None
    return blocks[0]

def _swap_ok(board, y0, x0, api, p):
    if x0 < 2:
        return None
    left = board[y0:y0+2, x0-2:x0]
    u = np.unique(left)
    if len(u) != 1 or u[0] == api.background:
        return None
    # left block must be isolated: the 2x2 further left must not be the same colour
    d = p["d"]
    if x0 >= d:
        leftleft = board[y0:y0+2, x0-d:x0-d+2]
        if (leftleft == u[0]).all():
            return None
    return u[0]

def applies(board, act, api, p):
    if act.action != 3:
        return False
    b = _agent_block(board, p)
    if b is None:
        return False
    return _swap_ok(board, b[0], b[1], api, p) is not None

def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, bool)
    b = _agent_block(board, p)
    if b is None:
        return out, claimed
    y0, x0 = b
    lc = _swap_ok(board, y0, x0, api, p)
    if lc is None:
        return out, claimed
    out[y0:y0+2, x0-2:x0] = p["agent"]
    out[y0:y0+2, x0:x0+2] = lc
    claimed[y0:y0+2, x0-2:x0+2] = True
    return out, claimed

RULE = "clicking an agent-colour tile inside the container region recolours that tile to the target colour"
PARAMS = {"agent": Colour(), "target": Colour(), "container": Region()}

def bind(board0, api):
    if not api.layout:
        return {"agent": api.background, "target": api.background, "container": None}
    cont = api.layout[0]
    counts = {}
    for o in objects(board0, api):
        if o.colour == cont.colour:
            continue
        if o.box[0] > cont.y0 and o.box[1] < cont.y1 and o.box[2] > cont.x0 and o.box[3] < cont.x1:
            counts[o.colour] = counts.get(o.colour, 0) + o.size
    if not counts:
        return {"agent": cont.colour, "target": cont.colour, "container": cont}
    items = sorted(counts.items(), key=lambda kv: -kv[1])
    agent = items[0][0]
    target = items[1][0] if len(items) > 1 else items[0][0]
    return {"agent": agent, "target": target, "container": cont}

def _inside(obj, cont):
    return (obj.box[0] > cont.y0 and obj.box[1] < cont.y1 and
            obj.box[2] > cont.x0 and obj.box[3] < cont.x1)

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    cont = p["container"]
    if cont is None:
        return False
    r, c = act.click
    if board[r, c] != p["agent"]:
        return False
    obj = object_at(board, api, (r, c))
    if obj is None or obj.colour != p["agent"]:
        return False
    return _inside(obj, cont)

def predict(board, act, api, p):
    r, c = act.click
    obj = object_at(board, api, (r, c))
    if obj is None:
        return unchanged(board, np.zeros((64, 64), bool))
    return recolour(board, api, obj, p["target"])

RULE = "Clicking a tile of the agent colour that lies inside the big box recolours that tile to the target colour."
PARAMS = {"agent": Colour(), "target": Colour()}

def bind(board, api):
    cols = list(api.colours)
    a = cols[0]
    t = cols[1] if len(cols) > 1 else a
    return {"agent": a, "target": t}

def _container(board, api, clicked):
    cont = None
    for o in objects(board, api):
        if (o.size > clicked.size and
            o.box[0] <= clicked.box[0] and o.box[1] >= clicked.box[1] and
            o.box[2] <= clicked.box[2] and o.box[3] >= clicked.box[3]):
            if cont is None or o.size > cont.size:
                cont = o
    return cont

def applies(board, act, api, p):
    if act.click is None:
        return False
    clicked = object_at(board, api, act.click)
    if clicked is None or clicked.colour != p["agent"]:
        return False
    return _container(board, api, clicked) is not None

def predict(board, act, api, p):
    clicked = object_at(board, api, act.click)
    return recolour(board, api, clicked, p["target"])

RULE = "Clicking a source-colour 6x6 block inside the framed grid turns the whole block to the target colour"
PARAMS = {"src": Colour(), "dst": Colour()}

def _frame(api):
    best = None
    for r in api.layout:
        h = r.y1 - r.y0 + 1; w = r.x1 - r.x0 + 1
        area = h * w
        if area < 100 or r.size / area > 0.6:
            continue
        if best is None or area > best[0]:
            best = (area, r)
    return best[1] if best else None

def _comp(board, r, c, col):
    seen = np.zeros((64, 64), bool)
    stack = [(r, c)]; seen[r, c] = True; cells = []
    while stack:
        y, x = stack.pop(); cells.append((y, x))
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < 64 and 0 <= nx < 64 and not seen[ny, nx] and board[ny, nx] == col:
                seen[ny, nx] = True; stack.append((ny, nx))
    return cells

def _is_block(cells):
    ys = [y for y, x in cells]; xs = [x for y, x in cells]
    return len(cells) == 36 and max(ys) - min(ys) + 1 == 6 and max(xs) - min(xs) + 1 == 6

def bind(board0, api):
    f = _frame(api)
    if f is None:
        return {}
    seen = np.zeros((64, 64), bool)
    cols = []
    for r in range(f.y0 + 1, f.y1):
        for c in range(f.x0 + 1, f.x1):
            if board0[r, c] != api.background and not seen[r, c]:
                cells = _comp(board0, r, c, board0[r, c])
                for y, x in cells:
                    seen[y, x] = True
                if _is_block(cells):
                    cols.append(board0[r, c])
    uniq = list(dict.fromkeys(cols))
    if len(uniq) >= 2:
        return {"src": uniq[0], "dst": uniq[1]}
    return {}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    if board[r, c] != p["src"]:
        return False
    f = _frame(api)
    if f is None or not (f.y0 < r < f.y1 and f.x0 < c < f.x1):
        return False
    return _is_block(_comp(board, r, c, p["src"]))

def predict(board, act, api, p):
