base_RULE = "Clicking a full cell inside the container recolours it to the target colour"
PARAMS = {"target": Colour(), "container": Region()}

def base_bind(board0, api):
    if not api.layout:
        return None
    cont = api.layout[0]
    target = api.background
    sub = board0[cont.y0:cont.y1 + 1, cont.x0:cont.x1 + 1]
    vals, counts = np.unique(sub, return_counts=True)
    for i in np.argsort(-counts):
        if vals[i] != cont.colour:
            target = int(vals[i])
            break
    return {"target": target, "container": cont}

def _inside(cont, o):
    y0, y1, x0, x1 = o.box
    return y0 > cont.y0 and y1 < cont.y1 and x0 > cont.x0 and x1 < cont.x1

def base_applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    cont = p["container"]
    if cont is None:
        return False
    obj = object_at(board, api, act.click)
    if obj is None:
        return False
    if obj.colour == cont.colour or obj.colour == p["target"]:
        return False
    if not _inside(cont, obj):
        return False
    # must be a full cell, not a tiny speck of the same colour
    sizes = [o.size for o in objects(board, api, colour=obj.colour) if _inside(cont, o)]
    if not sizes or obj.size < max(sizes):
        return False
    return True

def base_predict(board, act, api, p):
    obj = object_at(board, api, act.click)
    if obj is None:
        return None
    out = board.copy()
    out[obj.mask] = p["target"]
    return out, obj.mask


# ---- written by S3's guard fitter (gb/s3_guards.py) from rule 8: base AND NOT guard ----
