RULE = "clicking a target-colour block inside the framed grid flips that whole block to the other grid colour"
PARAMS = {"target": Colour(), "frame": Region()}

def _union_bbox(api, colour, minsize):
    ys, xs = [], []
    for r in api.layout:
        if r.colour == colour and r.size >= minsize and r.y0 < 63:
            ys += [r.y0, r.y1]; xs += [r.x0, r.x1]
    if not ys:
        return None
    return (min(ys), max(ys), min(xs), max(xs))

def _component(mask, r, c):
    comp = np.zeros(mask.shape, dtype=bool)
    comp[r, c] = True
    stack = [(r, c)]
    while stack:
        y, x = stack.pop()
        for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < 64 and 0 <= nx < 64 and mask[ny, nx] and not comp[ny, nx]:
                comp[ny, nx] = True
                stack.append((ny, nx))
    return comp

def _grid_colours(api):
    cnt = {}
    for r in api.layout:
        if r.size >= 9 and r.y0 < 63:
            cnt[r.colour] = cnt.get(r.colour, 0) + 1
    return {c for c, n in cnt.items() if n >= 2}

def bind(board0, api):
    gc = _grid_colours(api)
    cols5 = {r.colour for r in api.layout if r.size >= 3 and r.y0 < 63}
    frame_colour = None
    for c in cols5:
        if c in gc or c == api.background:
            continue
        ub = _union_bbox(api, c, 3)
        if ub is None:
            continue
        y0, y1, x0, x1 = ub
        for r in api.layout:
            if r.size >= 9 and r.y0 < 63 and r.colour in gc and r.colour != c:
                if r.y0 >= y0 and r.y1 <= y1 and r.x0 >= x0 and r.x1 <= x1:
                    frame_colour = c
                    break
        if frame_colour is not None:
            break
    frame = None
    if frame_colour is not None:
        cands = [r for r in api.layout if r.colour == frame_colour and r.size >= 3 and r.y0 < 63]
        if cands:
            frame = max(cands, key=lambda r: r.size)
    cnt = {}
    for r in api.layout:
        if r.size >= 9 and r.y0 < 63 and r.colour in gc:
            cnt[r.colour] = cnt.get(r.colour, 0) + 1
    target = max(cnt, key=lambda c: cnt[c]) if cnt else 0
    return {"target": target, "frame": frame}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None or p["frame"] is None:
        return False
    r, c = act.click
    if board[r, c] != p["target"]:
        return False
    comp = _component(board == p["target"], r, c)
    if comp.sum() < 4:
        return False
    ub = _union_bbox(api, p["frame"].colour, 3)
    if ub is None:
        return False
    ys, xs = np.where(comp)
    return (ys.min() >= ub[0] and ys.max() <= ub[1] and xs.min() >= ub[2] and xs.max() <= ub[3])

def predict(board, act, api, p):
    r, c = act.click
    comp = _component(board == p["target"], r, c)
    cnt = {}
    for rg in api.layout:
        if rg.size >= 9 and rg.y0 < 63 and rg.colour != p["frame"].colour:
            cnt[rg.colour] = cnt.get(rg.colour, 0) + 1
    cand = [col for col in cnt if col != p["target"]]
    result = max(cand, key=lambda col: cnt[col]) if cand else p["target"]
    out = board.copy()
    out[comp] = result
    return out, comp

RULE = "ACTION4 moves the agent 2x2 block two cells horizontally (dir) onto the solid 2x2 block there; the landed cells become the agent colour"
PARAMS = {"agent": Colour(), "dir": Choice([1, -1])}

def bind(board, api):
    agent = api.background
    for o in objects(api.first, api):
        if o.size == 4 and (o.box[1]-o.box[0]+1) == 2 and (o.box[3]-o.box[2]+1) == 2:
            agent = o.colour
            break
    return {"agent": agent, "dir": 1}

def _dest(board, api, p):
    me = find_object(board, api, p["agent"])
    if me is None:
        return None
    r0, r1, c0, c1 = me.box
    if me.size != 4 or (r1-r0+1) != 2 or (c1-c0+1) != 2:
        return None
    cc0 = c1+1 if p["dir"] == 1 else c0-2
    cc1 = cc0+1
    if cc0 < 0 or cc1 >= 64:
        return None
    reg = board[r0:r1+1, cc0:cc1+1]
    if reg.shape != (2,2) or len(np.unique(reg)) != 1:
        return None
    if reg[0,0] == api.background:
        return None
    return (r0, r1, cc0, cc1)

def applies(board, act, api, p):
    if act.action != 4:
        return False
    return _dest(board, api, p) is not None

def predict(board, act, api, p):
