    r0, r1, cc0, cc1 = d
    out = board.copy()
    out[r0:r1+1, cc0:cc1+1] = p["agent"]
    claimed = np.zeros((64,64), dtype=bool)
    claimed[r0:r1+1, cc0:cc1+1] = True
