RULE = "clicking a blue block shifts the small shape horizontally by step (right for the upper block, left for the lower)"
PARAMS = {"agent": Colour(), "step": Int(1, 8)}

def _bar(api):
    for r in api.layout:
        if (r.y1 - r.y0 + 1) <= 8 and (r.x1 - r.x0 + 1) >= 16:
            return r
    return None

def _agent_regions(api, p):
    regs = [r for r in api.layout if r.colour == p["agent"]]
    regs.sort(key=lambda r: r.y0)
    return regs

def _shape_cols(api, p):
    bar = _bar(api)
    bg = api.background
    gray = api.layout[0].colour
    cols = set()
    for r in api.layout:
        if r.size < 100 and r.colour not in (p["agent"], bg, gray):
            if bar is not None and not (r.y1 < bar.y0 or r.y0 > bar.y1):
                continue
            cols.add(r.colour)
    return sorted(cols)

def bind(board0, api):
    cand = {}
    for r in api.layout:
        if r.x1 == 63 and r.size < 100:
            cand.setdefault(r.colour, []).append(r)
    agent = None
    for c, rs in cand.items():
        if len(rs) >= 2:
            agent = c
            break
    return {"agent": agent, "step": 4} if agent is not None else {}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    if board[r, c] != p["agent"]:
        return False
    regs = _agent_regions(api, p)
    if len(regs) < 2:
        return False
    if _bar(api) is None:
        return False
    if len(_shape_cols(api, p)) < 2:
        return False
    if not any(rr.y0 <= r <= rr.y1 and rr.x0 <= c <= rr.x1 for rr in regs):
        return False
    return True

def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, dtype=bool)
    regs = _agent_regions(api, p)
    upper = regs[0]
    r, c = act.click
    if upper.y0 <= r <= upper.y1 and upper.x0 <= c <= upper.x1:
        d = p["step"]
    else:
        d = -p["step"]
    bar = _bar(api)
    H, W = board.shape
    for col in _shape_cols(api, p):
        mask = (board == col) & ~api.ticker
        if bar is not None:
            mask[bar.y0:bar.y1 + 1, :] = False
        if not mask.any():
            continue
        new = np.zeros_like(mask)
        if d > 0:
            new[:, d:W] = mask[:, :W - d]
        else:
            new[:, :W + d] = mask[:, -d:]
        out[new] = col
        claimed |= new
    return out, claimed

RULE = "clicking a colour swatch in the top bar slides the indicator line to under that swatch"
PARAMS = {"width": Int(1, 8)}

def _main0(board, bg):
    for r in range(board.shape[0]):
        if (board[r] == bg).mean() > 0.5:
            return r
    return board.shape[0]

def _bar_x0(board, bar_bg):
    for c in range(board.shape[1]):
        if board[0, c] == bar_bg:
            return c
    return 0

def _swatch_center(board, r, c, main0, bar_x0, W, col):
    for r0 in range(max(0, r - 2), min(main0 - 2, r) + 1):
        for c0 in range(max(bar_x0, c - 2), min(W - 3, c) + 1):
            if (board[r0:r0 + 3, c0:c0 + 3] == col).all():
                return c0 + 1
    return None

def _line(board, main0, bar_bg, bar_x0, W, width):
    for r in range(main0 - 1, -1, -1):
        for c in range(bar_x0, W - (width - 1)):
            k = int(board[r, c])
            if k == bar_bg:
                continue
            if (board[r, c:c + width] == k).all() and \
               (c == bar_x0 or int(board[r, c - 1]) != k) and \
               (c + width >= W or int(board[r, c + width]) != k):
                return r, c, c + width - 1, k
    return None

def bind(board0, api):
    return {"width": 5}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    bg = api.background
    W = board.shape[1]
    main0 = _main0(board, bg)
    if r >= main0:
        return False
    bar_bg = int(board[0, W // 2])
    col = int(board[r, c])
    if col == bar_bg:
        return False
    bar_x0 = _bar_x0(board, bar_bg)
    if _swatch_center(board, r, c, main0, bar_x0, W, col) is None:
        return False
    return _line(board, main0, bar_bg, bar_x0, W, p["width"]) is not None

def predict(board, act, api, p):
    out = board.copy()
    claimed = np.zeros(board.shape, bool)
    r, c = act.click
    bg = api.background
    W = board.shape[1]
    main0 = _main0(board, bg)
    bar_bg = int(board[0, W // 2])
    bar_x0 = _bar_x0(board, bar_bg)
    col = int(board[r, c])
    width = p["width"]
    center = _swatch_center(board, r, c, main0, bar_x0, W, col)
    li = _line(board, main0, bar_bg, bar_x0, W, width)
    if center is None or li is None:
        return out, claimed
    lr, oc0, oc1, linec = li
    track = int(np.bincount(board[lr, bar_x0:], minlength=16).argmax())
    half = width // 2
    nc0, nc1 = center - half, center + half
    out[lr, oc0:oc1 + 1] = track
    out[lr, nc0:nc1 + 1] = linec
    claimed[lr, oc0:oc1 + 1] = True
    claimed[lr, nc0:nc1 + 1] = True
    return out, claimed

RULE = "clicking a paint swatch slides the 1-row indicator bar to sit under that swatch, leaving the track colour in its old cells"
PARAMS = {"bar": Colour(), "track": Colour()}

def _box(o):
    t, b, l, r = o.box
    return t, b, l, r

def bind(board, api):
    objs = objects(board, api)
    frames = [o for o in objs if (_box(o)[1] - _box(o)[0]) == 4 and (_box(o)[3] - _box(o)[2]) == 4]
    if not frames:
        return None
    row = min(frames, key=lambda o: _box(o)[0]).box[1] + 1
    row_objs = [o for o in objs if (_box(o)[1] - _box(o)[0]) == 0 and _box(o)[0] == row]
    if len(row_objs) < 2:
        return None
    return {"bar": min(row_objs, key=lambda o: o.size).colour,
            "track": max(row_objs, key=lambda o: o.size).colour}

def _locate(board, act, api, p):
    if act.click is None:
        return None
    sw = object_at(board, api, act.click)
    if sw is None:
        return None
    st, sb, sl, sr = _box(sw)
    cands = [o for o in objects(board, api)
             if o.colour != sw.colour
             and _box(o)[0] <= st and _box(o)[1] >= sb
             and _box(o)[2] <= sl and _box(o)[3] >= sr]
    if not cands:
        return None
    frame = min(cands, key=lambda o: o.size)
    row = frame.box[1] + 1
    bar = None
    for o in objects(board, api):
        if o.colour == p["bar"] and (_box(o)[1] - _box(o)[0]) == 0 and _box(o)[0] == row:
            bar = o
            break
    if bar is None:
        return None
    shift = (frame.box[2] + frame.box[3]) // 2 - (bar.box[2] + bar.box[3]) // 2
    return frame, bar, shift

def applies(board, act, api, p):
    loc = _locate(board, act, api, p)
    if loc is None:
        return False
    frame, bar, shift = loc
    if shift == 0:
        return False
    if bar.box[2] + shift < 0 or bar.box[3] + shift > 63:
        return False
    for c in range(bar.box[2] + shift, bar.box[3] + shift + 1):
        if board[bar.box[0], c] != p["track"]:
            return False
    return True

def predict(board, act, api, p):
    loc = _locate(board, act, api, p)
    if loc is None:
        return None
    frame, bar, shift = loc
    if shift == 0:
        return unchanged(board, bar)
    return translate(board, api, bar, 0, shift, behind=p["track"])

RULE = "clicking a palette slot recolors the framed play shape to the slot's colour and slides the indicator bar under that slot"
PARAMS = {"frame": Colour()}

def bind(board, api):
    objs = objects(board, api)
    for f in objs:
        if f.size > 40:
            continue
        t, b, l, r = f.box
        for s in objs:
            if s is f or s.size >= 20 or s.size >= f.size:
                continue
            st, sb, sl, sr = s.box
            if st == t + 1 and sb == b - 1 and sl == l + 1 and sr == r - 1:
                return {"frame": f.colour}
    return {"frame": api.background}

def _frames(board, api, p):
    return [o for o in objects(board, api) if o.colour == p["frame"] and o.size <= 40]

def _slot(board, api, act, p):
    if act.click is None:
        return None
    s = object_at(board, api, act.click)
    if s is None:
        return None
    for f in _frames(board, api, p):
        t, b, l, r = f.box
        st, sb, sl, sr = s.box
        if st == t + 1 and sb == b - 1 and sl == l + 1 and sr == r - 1:
            return s, f
    return None

def _bar(board, api, p):
    fr = _frames(board, api, p)
    if not fr:
        return None
    row = min(f.box[1] for f in fr) + 1
    L = min(f.box[2] for f in fr)
    R = max(f.box[3] for f in fr)
    w = fr[0].box[3] - fr[0].box[2] + 1
    for o in objects(board, api):
        if (o.box[0] == row and o.box[1] == row and o.box[2] >= L and o.box[3] <= R
                and o.box[3] - o.box[2] + 1 == w):
            return o
    return None

def _framed(board, api, o):
    t, b, l, r = o.box
    if t <= 0 or b >= 63 or l <= 0 or r >= 63:
        return None
    ring = []
    for c in range(l - 1, r + 2):
        ring.append(board[t - 1, c]); ring.append(board[b + 1, c])
    for rr in range(t, b + 1):
        ring.append(board[rr, l - 1]); ring.append(board[rr, r + 1])
    ring = np.array(ring)
    vals, counts = np.unique(ring, return_counts=True)
    c = vals[np.argmax(counts)]
    if c == api.background or counts.max() < 0.75 * len(ring):
        return None
    return c

def _main(board, api, bar):
    objs = objects(board, api)
    if bar is not None:
        objs = [o for o in objs if o.box[0] > bar.box[0]]
    cands = [o for o in objs if _framed(board, api, o) is not None]
    if not cands:
        return None
    return max(cands, key=lambda o: o.size)

def applies(board, act, api, p):
    return _slot(board, api, act, p) is not None

def predict(board, act, api, p):
    res = _slot(board, api, act, p)
    if res is None:
        return unchanged(board, np.zeros((64, 64), bool))
    slot, frame = res
    out = board.copy()
    claimed = np.zeros((64, 64), bool)
    bar = _bar(board, api, p)
    main = _main(board, api, bar)
    if main is not None:
        out[main.mask] = slot.colour
        claimed[main.mask] = True
    if bar is not None:
        nl, nr = frame.box[2], frame.box[3]
        if not (bar.box[2] == nl and bar.box[3] == nr):
            row = bar.box[0]
            fr = _frames(board, api, p)
            L = min(f.box[2] for f in fr)
            R = max(f.box[3] for f in fr)
            track = None
            for c in range(L, R + 1):
                if not (bar.box[2] <= c <= bar.box[3]):
                    track = int(board[row, c])
                    break
            if track is not None:
                out[bar.mask] = track
                claimed[bar.mask] = True
            out[row, nl:nr + 1] = bar.colour
            claimed[row, nl:nr + 1] = True
    return out, claimed

RULE = "clicking the edge button shifts the gray block by step, left if the button is in the lower half else right"
PARAMS = {"button": Colour(), "block": Colour(), "step": Int(1, 8)}

def bind(board, api):
    return {"button": api.background, "block": api.background, "step": 1}

def _dir(board, act, p):
    return p["step"] if act.click[0] < board.shape[0] // 2 else -p["step"]

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    if board[act.click[0], act.click[1]] != p["button"]:
        return False
    obj = find_object(board, api, p["block"])
    if obj is None:
        return False
    d = _dir(board, act, p)
    c0, c1 = obj.box[2], obj.box[3]
    if c0 + d < 0 or c1 + d >= board.shape[1]:
        return False
    return True

def predict(board, act, api, p):
    obj = find_object(board, api, p["block"])
    if obj is None:
        return board.copy(), np.zeros(board.shape, dtype=bool)
    d = _dir(board, act, p)
    r0, r1, c0, c1 = obj.box
    newmask = np.zeros(board.shape, dtype=bool)
    newmask[r0:r1 + 1, c0 + d:c1 + d + 1] = obj.mask[r0:r1 + 1, c0:c1 + 1]
    out = board.copy()
    out[newmask] = p["block"]
    return out, newmask

RULE = "Clicking the right (non-rectangular) agent-colour shape toggles the left agent-colour rectangle between the top-right and bottom-left corners of its square socket."
PARAMS = {"agent": Colour()}

def bind(board0, api):
    W = board0.shape[1]
    best = None
    for o in objects(board0, api):
        t, b, l, r = o.box
        if o.size != (b - t + 1) * (r - l + 1) and l >= W // 2:
            if best is None or o.size > best.size:
                best = o
    return {"agent": best.colour if best is not None else api.background}

def _rect(o):
    t, b, l, r = o.box
    return o.size == (b - t + 1) * (r - l + 1)

def _target(o):
    t, b, l, r = o.box
    h, w, S = b - t + 1, r - l + 1, (b - t + 1) + (r - l + 1)
    if h > w:  # currently top-right -> target bottom-left
        tr1, tc0 = t + S - 1, r - S + 1
        return (t + h, tr1, tc0, tc0 + h - 1)
    else:      # currently bottom-left -> target top-right
        tr0, tc1 = b - S + 1, l + S - 1
        return (tr0, tr0 + w - 1, tc1 - h + 1, tc1)

def _analyze(board, api, act, p):
    if act.click is None:
        return None
    H, W = board.shape
    r, c = act.click
    clicked = object_at(board, api, (r, c))
    if clicked is None or clicked.colour != p["agent"] or _rect(clicked):
        return None
    cands = [o for o in objects(board, api, colour=p["agent"])
             if o.box != clicked.box and _rect(o)]
    if len(cands) != 1:
        return None
    L = cands[0]
    t_r0, t_r1, t_c0, t_c1 = _target(L)
    if not (0 <= t_r0 <= t_r1 < H and 0 <= t_c0 <= t_c1 < W):
        return None
    sub = board[t_r0:t_r1 + 1, t_c0:t_c1 + 1]
    behind = sub[(t_r1 - t_r0) // 2, (t_c1 - t_c0) // 2]
    if not np.all(sub == behind):
        return None
    tmask = np.zeros((H, W), bool)
    tmask[t_r0:t_r1 + 1, t_c0:t_c1 + 1] = True
    if np.any(tmask & L.mask):
        return None
    return L, (t_r0, t_r1, t_c0, t_c1), behind

def applies(board, act, api, p):
    return _analyze(board, api, act, p) is not None

def predict(board, act, api, p):
    a = _analyze(board, api, act, p)
    if a is None:
        return unchanged(board, np.zeros(board.shape, bool))
    L, (t_r0, t_r1, t_c0, t_c1), behind = a
    out = board.copy()
    out[L.mask] = behind
    out[t_r0:t_r1 + 1, t_c0:t_c1 + 1] = L.colour
    claimed = L.mask.copy()
    claimed[t_r0:t_r1 + 1, t_c0:t_c1 + 1] = True
    return out, claimed

RULE = "ACTION4 swaps the agent 2x2 block with the solid 2x2 block two columns to its side"
PARAMS = {"agent": Colour(), "dir": Choice([1, -1])}

def _candidates(board, p, api):
    a, d = p["agent"], p["dir"]
    m = (board == a)
    u = m & np.roll(m, -1, axis=0) & np.roll(m, -1, axis=1) & np.roll(m, -1, axis=0) & np.roll(m, -1, axis=1)
    # top-left of any 2x2 agent block: cell is agent and cell below-right is agent
    u = m & np.roll(m, -1, axis=0) & np.roll(m, -1, axis=1) & np.roll(m, -2, axis=0) & np.roll(m, -2, axis=1)
    out = []
    for y, x in zip(*np.nonzero(u)):
        if y + 2 >= 64 or x + 2 >= 64:
            continue
        x2 = x + 2 * d
        if x2 < 0 or x2 + 2 > 64:
            continue
        t = board[y:y+2, x2:x2+2]
        cols = np.unique(t)
        if len(cols) == 1 and cols[0] != a and cols[0] != api.background:
            out.append((y, x, x2, int(cols[0])))
    return out

def bind(board0, api):
    if not api.layout:
        return {}
    r = min(api.layout, key=lambda r: (r.size, -r.y1))
    return {"agent": r.colour, "dir": 1}

def applies(board, act, api, p):
    if act.action != 4:
        return False
    return len(_candidates(board, p, api)) == 1

def predict(board, act, api, p):
    y, x, x2, t = _candidates(board, p, api)[0]
    a = p["agent"]
    out = board.copy()
    out[y:y+2, x:x+2] = t
    out[y:y+2, x2:x2+2] = a
    claimed = np.zeros((64, 64), bool)
    claimed[y:y+2, x:x+2] = True
    claimed[y:y+2, x2:x2+2] = True
    return out, claimed

RULE = "ACTION3 swaps the agent's box with the solid box across a solid bar box to its left; the agent re-docks at the middle of the new box's left edge"
PARAMS = {"agent": Colour()}

def _hole_box(board, api, p):
    for o in objects(board, api):
        h = o.box[1] - o.box[0] + 1
        w = o.box[3] - o.box[2] + 1
        if w < 2 or h < 2 or o.size != w * h - 1:
            continue
        sub = o.mask[o.box[0]:o.box[1] + 1, o.box[2]:o.box[3] + 1]
        ys, xs = np.where(~sub)
        if len(ys) != 1:
            continue
        hr, hc = o.box[0] + int(ys[0]), o.box[2] + int(xs[0])
        if board[hr, hc] != p["agent"]:
            continue
        ob = object_at(board, api, (hr, hc))
        if ob is None or ob.size != 1:
            continue
        return o
    return None

def _left_solid(board, api, o):
    h = o.box[1] - o.box[0] + 1
    w = o.box[3] - o.box[2] + 1
    for q in objects(board, api):
        if q is o:
            continue
        if q.box[0] != o.box[0] or q.box[1] != o.box[1]:
            continue
        if q.box[3] - q.box[2] + 1 != w:
            continue
        if q.size != h * w:
            continue
        if q.box[3] != o.box[2] - 1:
            continue
        return q
    return None

def _find(board, api, p):
    A = _hole_box(board, api, p)
    if A is None:
        return None
    bar = _left_solid(board, api, A)
    if bar is None:
        return None
    B = _left_solid(board, api, bar)
    if B is None:
        return None
    return A, B

def bind(board, api):
    for o in objects(board, api):
        h = o.box[1] - o.box[0] + 1
        w = o.box[3] - o.box[2] + 1
        if w < 2 or h < 2 or o.size != w * h - 1:
            continue
        sub = o.mask[o.box[0]:o.box[1] + 1, o.box[2]:o.box[3] + 1]
        ys, xs = np.where(~sub)
        if len(ys) == 1:
            hr, hc = o.box[0] + int(ys[0]), o.box[2] + int(xs[0])
            if board[hr, hc] != api.background:
                return {"agent": int(board[hr, hc])}
    return {"agent": int(api.background)}

def applies(board, act, api, p):
    if act.action != 3:
        return False
    return _find(board, api, p) is not None

def predict(board, act, api, p):
    r = _find(board, api, p)
    if r is None:
        return unchanged(board, np.zeros((64, 64), bool))
    A, B = r
    out = board.copy()
    out[A.box[0]:A.box[1] + 1, A.box[2]:A.box[3] + 1] = B.colour
    out[B.box[0]:B.box[1] + 1, B.box[2]:B.box[3] + 1] = A.colour
    out[(B.box[0] + B.box[1]) // 2, B.box[2]] = p["agent"]
    claimed = np.zeros((64, 64), bool)
    claimed[A.box[0]:A.box[1] + 1, A.box[2]:A.box[3] + 1] = True
    claimed[B.box[0]:B.box[1] + 1, B.box[2]:B.box[3] + 1] = True
    return out, claimed

RULE = "ACTION4 spins a flat landscape tile in its slot into a diamond; the tile's cells left of the new diamond become background."
PARAMS = {"tile": Colour(), "shift": Int(1, 8)}

def _full_rect(r):
    b = r.box
    return (b[1] - b[0] + 1) * (b[3] - b[2] + 1) == r.size

def _landscape(r):
    b = r.box
    return (b[3] - b[2] + 1) > (b[1] - b[0] + 1)

def bind(board, api):
    best = None
    for r in api.layout:
        if _full_rect(r) and r.size >= 20:
            if best is None or r.size > best.size:
                best = r
    if best is None:
        return None
    return {"tile": best.colour, "shift": 7}

def applies(board, act, api, p):
    if act.action != 4:
        return False
    t = find_object(board, api, p["tile"])
    if t is None or t.size < 20:
        return False
    return _full_rect(t) and _landscape(t)

def predict(board, act, api, p):
    t = find_object(board, api, p["tile"])
    if t is None or not _full_rect(t):
        return unchanged(board, np.zeros(board.shape, dtype=bool))
    out = board.copy()
    tb = t.box
    cols = np.arange(board.shape[1])[None, :]
    mask = t.mask & (cols < tb[2] + p["shift"])
    out[mask] = api.background
    return out, mask

RULE = "ACTION1 swaps the 3x3 agent block with the 3x3 slot step rows above, but only when the agent's dot is at the bottom-centre of the block; the dot then sits at the top-centre of the new block"
PARAMS = {"agent": Colour(), "step": Int(1, 8)}

def _box(o):
    return o.box  # (top, bottom, left, right)

def _locate(board, api, p):
    ag = find_object(board, api, p["agent"])
    if ag is None:
        return None
    ay0, ay1, ax0, ax1 = _box(ag)
    if ay1 - ay0 != 2 or ax1 - ax0 != 2:
        return None
    dot = None
    for o in objects(board, api):
        if o.size == 1:
            oy0, oy1, ox0, ox1 = _box(o)
            if oy0 == oy1 and ox0 == ox1 and ay0 <= oy0 <= ay1 and ax0 <= ox0 <= ax1:
                dot = o
                break
    if dot is None:
        return None
    dy0, dy1, dx0, dx1 = _box(dot)
    # swap only when the dot is at the bottom-centre of the agent block
    if dy0 != ay1 or dx0 != (ax0 + ax1) // 2:
        return None
    target = None
    for o in objects(board, api):
        if o is ag or o is dot:
            continue
        ty0, ty1, tx0, tx1 = _box(o)
        if (ty1 - ty0 == 2 and tx1 - tx0 == 2 and tx0 == ax0 and tx1 == ax1
                and ty0 == ay0 - p["step"] and o.colour != p["agent"] and o.size == 9):
            target = o
            break
    if target is None:
        return None
    return ag, dot, target

def bind(board0, api):
    objs = objects(board0, api)
    dot = None
    for o in objs:
        if o.size == 1:
            dot = o
            break
    agent = None
    if dot is not None:
        dy0, dy1, dx0, dx1 = _box(dot)
        for o in objs:
            if o is dot:
                continue
            oy0, oy1, ox0, ox1 = _box(o)
            if oy1 - oy0 == 2 and ox1 - ox0 == 2 and oy0 <= dy0 <= oy1 and ox0 <= dx0 <= ox1:
                agent = o
                break
    if agent is None:
        agent = objs[0] if objs else None
    return {"agent": agent.colour if agent is not None else api.background, "step": 6}

def applies(board, act, api, p):
    if act.action != 1:
        return False
    return _locate(board, api, p) is not None

def predict(board, act, api, p):
    loc = _locate(board, api, p)
    if loc is None:
        return None, None
    ag, dot, target = loc
    ay0, ay1, ax0, ax1 = _box(ag)
    ty0, ty1, tx0, tx1 = _box(target)
    dy0, dy1, dx0, dx1 = _box(dot)
    out = board.copy()
    out[ty0:ty1 + 1, tx0:tx1 + 1] = p["agent"]
    out[ty0, dx0] = dot.colour          # dot moves to top-centre of new block
    out[ay0:ay1 + 1, ax0:ax1 + 1] = target.colour
    claimed = np.zeros((64, 64), dtype=bool)
    claimed[ty0:ty1 + 1, tx0:tx1 + 1] = True
    claimed[ay0:ay1 + 1, ax0:ax1 + 1] = True
    return out, claimed

RULE = "ACTION4 slides the square agent right by step into a slot holding a token; the slot becomes the agent ring with the agent's old centre colour."
PARAMS = {"agent": Colour(), "step": Int(1, 8)}

def bind(board, api):
    best = None
    for o in objects(board, api):
        y0, y1, x0, x1 = o.box
        side = y1 - y0 + 1
        if x1 - x0 + 1 != side or side < 3:
            continue
        if o.size == side * side - 1:
            if best is None or side > best[0]:
                best = (side, o)
    if best is not None:
        return {"agent": best[1].colour, "step": 6}
    return {"agent": api.colours[0] if api.colours else api.background, "step": 6}

def _track(board, api):
    o = objects(board, api)
    return o[0].colour if o else None

def _agent_side(board, api, p):
    best = None
    for o in objects(board, api, p["agent"]):
        y0, y1, x0, x1 = o.box
        side = y1 - y0 + 1
        if x1 - x0 + 1 != side or side < 3:
            continue
        if o.size == side * side - 1:
            if best is None or side > best:
                best = side
    return best

def _pick(board, api, p):
    tr = _track(board, api)
    if tr is None:
        return None
    step = p["step"]
    W = board.shape[1]
    side = _agent_side(board, api, p)
    if side is None:
        return None
    full = side * side - 1
    small = (side - 2) ** 2
    cands = []
    for o in objects(board, api, p["agent"]):
        if o.size != full:
            continue
        y0, y1, x0, x1 = o.box
        nx0, nx1 = x0 + step, x1 + step
        if nx0 < 0 or nx1 >= W:
            continue
        d = board[y0:y1 + 1, nx0:nx1 + 1]
        if np.any(d == api.background):
            continue
        n = int(np.sum(~np.isin(d, [api.background, tr, p["agent"]])))
        if n in (full, small):
            cands.append(o)
    return cands[0] if cands else None

def applies(board, act, api, p):
    if act.action != 4:
        return False
    return _pick(board, api, p) is not None

def predict(board, act, api, p):
    o = _pick(board, api, p)
    if o is None:
        return unchanged(board, np.zeros(board.shape, bool))
    y0, y1, x0, x1 = o.box
    step = p["step"]
    nx0, nx1 = x0 + step, x1 + step
    out = board.copy()
    out[y0:y1 + 1, nx0:nx1 + 1] = p["agent"]
    cy, cx = (y0 + y1) // 2, (x0 + x1) // 2
    out[cy, cx + step] = board[cy, cx]
    claimed = np.zeros(board.shape, bool)
    claimed[y0:y1 + 1, nx0:nx1 + 1] = True
    return out, claimed

RULE = "clicking a blue tile in the framed grid advances the bottom progress bar by two cells (bar_from -> bar_to) at the left edge of the right-hand bar_to run"
PARAMS = {"tile": Colour(), "bar_from": Colour(), "bar_to": Colour()}

def _bar_state(board, api, p):
    nb = (board != api.background).sum(axis=1)
    bar_row = int(np.argmax(nb))
    row = board[bar_row]
    is_to = (row == p["bar_to"])
    is_from = (row == p["bar_from"])
    not_to = ~is_to
    if not_to.any():
        suffix = 64 - int(np.where(not_to)[0].max()) - 1
    else:
        suffix = 64
    if not (0 < suffix < 64):
        return bar_row, None
    c2 = 64 - suffix - 1
    c1 = c2 - 1
    if c1 < 0 or not (is_from[c1] and is_from[c2]):
        return bar_row, None
    return bar_row, (c1, c2)

def _frame_bbox(api, p):
    cands = [r for r in api.layout
             if r.colour not in (p["tile"], p["bar_from"], p["bar_to"])
             and r.colour != api.background]
    if not cands:
        return None
    f = max(cands, key=lambda r: r.size)
    return (f.y0, f.x0, f.y1, f.x1)

def bind(board0, api):
    nb = (board0 != api.background).sum(axis=1)
    bar_row = int(np.argmax(nb))
    row = board0[bar_row]
    present = [c for c in api.colours if (row == c).any() and c != api.background]
    bar_to = int(row[-1]) if row[-1] != api.background else (present[0] if present else 0)
    bar_from = [c for c in present if c != bar_to][0] if len(present) > 1 else bar_to
    mask = (board0 != api.background) & (board0 != bar_from) & (board0 != bar_to)
    vals, counts = np.unique(board0[mask], return_counts=True)
    tile = int(vals[np.argmax(counts)]) if len(vals) else 0
    return {"tile": tile, "bar_from": bar_from, "bar_to": bar_to}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    if board[r, c] != p["tile"]:
        return False
    bb = _frame_bbox(api, p)
    if bb is None:
        return False
    y0, x0, y1, x1 = bb
    if not (y0 <= r <= y1 and x0 <= c <= x1):
        return False
    _, seg = _bar_state(board, api, p)
    return seg is not None

def predict(board, act, api, p):
    out = board.copy()
    bar_row, seg = _bar_state(board, api, p)
    c1, c2 = seg
    out[bar_row, c1] = p["bar_to"]
    out[bar_row, c2] = p["bar_to"]
    claimed = np.zeros(board.shape, dtype=bool)
    claimed[bar_row, c1] = True
    claimed[bar_row, c2] = True
    return out, claimed

RULE = "clicking an agent tile in the container also turns the bar's second-rightmost left-colour cell to the right colour"
PARAMS = {"agent": Colour()}

def _bar_target(board, api):
    bg = api.background
    rows = np.where((board != bg).any(axis=1))[0]
    if len(rows) == 0:
        return None
    br = int(rows[-1])
    row = board[br]
    cols = np.where(row != bg)[0]
    if len(cols) < 2:
        return None
    L0 = int(cols[0])
    lc, rc = int(row[L0]), int(row[-1])
    if lc == rc:
        return None
    diff = np.where(row != lc)[0]
    if len(diff) == 0:
        return None
    t = int(diff[0]) - 2          # second-rightmost left-colour cell
    if t < L0 or int(row[t]) != lc:
        return None
    return (br, t, rc)

def bind(board, api):
    big = api.layout[0]
    cands = []
    for o in objects(board, api):
        if o.colour == big.colour:
            continue
        t, b, l, r = o.box
        if big.y0 <= t and b <= big.y1 and big.x0 <= l and r <= big.x1 and 10 <= o.size <= 200:
            cands.append(o.colour)
    if not cands:
        return {"agent": big.colour}
    best, bn = cands[0], 0
    for c in set(cands):
        n = cands.count(c)
        if n > bn:
            bn, best = n, c
    return {"agent": best}

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    clicked = object_at(board, api, act.click)
    if clicked is None or clicked.colour != p["agent"]:
        return False
    t, b, l, r = clicked.box
    inside = False
    for reg in api.layout:
        if reg.colour == clicked.colour or reg.size <= clicked.size:
            continue
        if reg.y0 <= t and b <= reg.y1 and reg.x0 <= l and r <= reg.x1:
            inside = True
            break
    if not inside:
        return False
    return _bar_target(board, api) is not None

def predict(board, act, api, p):
    info = _bar_target(board, api)
    if info is None:
        return board.copy(), np.zeros((64, 64), bool)
    br, t, rc = info
    out = board.copy()
    out[br, t] = rc
    claimed = np.zeros((64, 64), bool)
    claimed[br, t] = True
    return out, claimed

RULE = "Clicking an agent-colour tile inside the big box shifts the bottom bar: the step cells just left of the right-hand colour become that colour."
PARAMS = {"agent": Colour(), "grow": Colour(), "shrink": Colour(), "step": Int(1, 4)}


def _bar(board, p):
    H, W = board.shape
    for r in range(H - 1, -1, -1):
        if board[r, W - 1] == p["grow"] and board[r, 0] == p["shrink"]:
            x = W - 1
            while x > 0 and board[r, x - 1] == p["grow"]:
                x -= 1
            return r, x
    return None

def applies(board, act, api, p):
    if act.action != 6 or act.click is None:
        return False
    r, c = act.click
    if board[r, c] != p["agent"]:
        return False
    if not api.layout:
        return False
    box = api.layout[0]
    if not (box.y0 < r < box.y1 and box.x0 < c < box.x1):
        return False
    b = _bar(board, p)
    if b is None:
        return False
    br, x0 = b
    if x0 - p["step"] < 0:
        return False
    for k in range(p["step"]):
        if board[br, x0 - 1 - k] != p["shrink"]:
            return False
    return True

def predict(board, act, api, p):
    out = board.copy()
    br, x0 = _bar(out, p)
    claimed = np.zeros(out.shape, dtype=bool)
    for k in range(p["step"]):
        out[br, x0 - 1 - k] = p["grow"]
        claimed[br, x0 - 1 - k] = True
    return out, claimed
